package com.example.domain.model.i18n

internal object DuaTa2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("மூன்று குல்கள் (முஆவிதாத்)", "(சூரத்துல் இஹ்லாஸ்) சொல்: அல்லாஹ் ஒருவனே. அல்லாஹ் தேவையற்றவன். அவன் யாரையும் பெறவில்லை, யாராலும் பெறப்படவில்லை. அவனுக்கு இணையானவன் யாருமில்லை.\n\n(சூரத்துல் ஃபலக்) சொல்: விடியலின் இறைவனிடம் பாதுகாப்பு தேடுகிறேன் — அவன் படைத்தவற்றின் தீங்கிலிருந்து, இருள் சூழும் இரவின் தீங்கிலிருந்து, முடிச்சுகளில் ஊதுபவர்களின் தீங்கிலிருந்து, பொறாமைப்படுபவனின் தீங்கிலிருந்து.\n\n(சூரத்துன் நாஸ்) சொல்: மனிதர்களின் இறைவனிடம் பாதுகாப்பு தேடுகிறேன் — மனிதர்களின் அரசன், மனிதர்களின் நாயன் — வஸ்வாஸ் செய்யும் திரும்பிச் செல்பவனின் தீங்கிலிருந்து, மனிதர்களின் மார்பில் வஸ்வாஸ் ஊட்டுவோரின் — ஜின்களில் இருந்தோ மனிதர்களில் இருந்தோ.", "காலையும் மாலையும் மூன்று முறை; தூங்கும் முன் கைகளில் ஊதி உடல் மீது தடவுதல்.", "காலை மாலை மூன்று முறை ஓதுவது எல்லாவற்றிலும் இருந்து போதுமான பாதுகாப்பாகும்."),
        "dua_sabr" to DuaText("பொறுமை மற்றும் உறுதிக்காக", "எங்கள் இறைவா! எங்கள் மீது பொறுமையை பொழி, எங்கள் அடிகளை உறுதிப்படுத்து, காஃபிர் கூட்டத்திற்கு எதிராக எங்களுக்கு உதவி செய்.", "கஷ்டமான நேரங்களில்.", "தாலூதின் படையினரின் துஆ."),
        "dua_rabbana_innana_amanna" to DuaText("மன்னிப்பும் நரகத்திலிருந்து காப்பும்", "எங்கள் இறைவா! நாங்கள் ஈமான் கொண்டோம்; எங்கள் பாவங்களை மன்னி, நரக வேதனையிலிருந்து எங்களை காப்பாற்று.", "குர்ஆனிய துஆ.", "முத்தகீன்களின் குணாதிசயங்களில் குறிப்பிடப்பட்ட துஆ."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("எங்கள் காரியங்களில் நேர்மை (அஸ்ஹாபுல் கஹ்ஃப்)", "எங்கள் இறைவா! உன்னிடமிருந்து கருணையை வழங்கு, எங்கள் காரியங்களில் எங்களுக்கு நேர்மையை ஏற்படுத்தி வை.", "அஸ்ஹாபுல் கஹ்ஃபின் துஆ.", "முடிவுகள் மற்றும் கடினமான நிலைகளில் வழிகாட்டுதல்."),
        "dua_musa_faqir" to DuaText("ரிஸ்கிற்காக மூஸா (அலை) அவர்களின் துஆ", "என் இறைவா! நீ எனக்கு அருளும் எந்த நன்மைக்கும் நான் ஏங்குகிறேன்.", "ரிஸ்க் மற்றும் நன்மை தேடுவதற்கு — மதியனில் மூஸா (அலை) அவர்களின் துஆ.", "இந்த துஆவுக்குப் பின் அல்லாஹ் மூஸா (அலை) அவர்களுக்கு வீடு, வேலை, மனைவி அளித்தான்."),
        "dua_ayyub" to DuaText("நோயில் அய்யூப் (அலை) அவர்களின் துஆ", "(என் இறைவா!) எனக்கு துன்பம் வந்தது; நீ கருணையாளர்கள் எல்லோரிலும் மிகவும் கருணையுடையவன்.", "நோய் மற்றும் கஷ்டத்தில்.", "அல்லாஹ் அய்யூப் (அலை) அவர்களின் துன்பத்தை நீக்கினான்."),
        "dua_husn_khatimah" to DuaText("முஸ்லிமாய் மரணம் (யூஸுஃப் அலை)", "வானங்களையும் பூமியையும் படைத்தவா! நீயே உலகிலும் ஆகிரத்திலும் என் ஆதரவாளன். என்னை இஸ்லாம் நிலையில் மரணிக்கச் செய், நேர்மையானவர்களுடன் சேர்.", "நல்ல முடிவுக்கான துஆ.", "யூஸுஃப் (அலை) அவர்களின் துஆ."),
        "dua_shaitan_hamazat" to DuaText("ஷைத்தானின் வஸ்வாஸிலிருந்து பாதுகாப்பு", "என் இறைவா! ஷைத்தான்களின் வஸ்வாஸிலிருந்து உன்னிடம் பாதுகாப்பு தேடுகிறேன்; என் இறைவா! அவர்கள் என்னிடம் வருவதிலிருந்தும் (பாதுகாப்பு தேடுகிறேன்).", "ஷைத்தானிய வஸ்வாஸிலிருந்து பாதுகாப்பு.", "குர்ஆனிய பாதுகாப்பு துஆ."),
        "dua_bad_character" to DuaText("கெட்ட குணங்களிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! கெட்ட குணங்கள், கெட்ட செயல்கள், கெட்ட ஆசைகளிலிருந்து உன்னிடம் பாதுகாப்பு தேடுகிறேன்.", "கெட்ட குணங்கள், செயல்கள், ஆசைகளிலிருந்து பாதுகாப்பு.", "நபி ﷺ அவர்களின் பாதுகாப்பு துஆ."),
        "dua_zawal_nimah" to DuaText("நிஃமத் மாய்ந்துவிடுவதிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! உன் நிஃமத் மாய்வதிலிருந்தும், உன் ஆரோக்கியம் மாறுவதிலிருந்தும், உன் திடீர் வேதனையிலிருந்தும், உன் எல்லா கோபத்திலிருந்தும் உன்னிடம் பாதுகாப்பு தேடுகிறேன்.", "நிஃமத் மாய்வதிலிருந்தும் திடீர் துன்பத்திலிருந்தும் பாதுகாப்பு.", "நபி ﷺ அவர்களின் துஆ."),
        "dua_useless_knowledge" to DuaText("பயனற்ற அறிவிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! பயனற்ற அறிவிலிருந்தும், அஞ்சாத இதயத்திலிருந்தும், திருப்தி அடையாத மனசாட்சியிலிருந்தும், ஏற்கப்படாத துஆவிலிருந்தும் உன்னிடம் பாதுகாப்பு தேடுகிறேன்.", "பயனற்ற அறிவிலிருந்தும் அஞ்சாத இதயத்திலிருந்தும் பாதுகாப்பு.", "நபி ﷺ அவர்களின் பாதுகாப்பு துஆ."),
        "dua_beneficial_knowledge" to DuaText("பயனுள்ள அறிவும் ஹலால் ரிஸ்கும்", "யா அல்லாஹ்! பயனுள்ள அறிவையும், தூய ரிஸ்கையும், ஏற்கப்படும் செயலையும் உன்னிடம் தேடுகிறேன்.", "ஃபஜ்ர் தொழுகைக்குப் பின்.", "நபி ﷺ ஃபஜ்ர் ஸலாமுக்குப் பின் இதை ஓதுவார்கள்."),
        "dua_leprosy_diseases" to DuaText("கடுமையான நோய்களிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! வெண்குஷ்டம், பைத்தியம், தொழுநோய் மற்றும் எல்லா கடுமையான நோய்களிலிருந்தும் உன்னிடம் பாதுகாப்பு தேடுகிறேன்.", "கடுமையான நோய்களிலிருந்து பாதுகாப்பு.", "ஆரோக்கியத்தை பேண சுன்னத்தான துஆ."),
        "dua_fear_people" to DuaText("எதிரி அல்லது அத்துமீறுபவரின் பயம்", "யா அல்லாஹ்! நாங்கள் உன்னை அவர்களுக்கு எதிராக வைக்கிறோம்; அவர்களின் தீங்கிலிருந்து உன்னிடம் பாதுகாப்பு தேடுகிறோம்.", "ஒரு கூட்டம் அல்லது நபரிடமிருந்து தீங்கு வரும் என்று அஞ்சும்போது.", "நபி ﷺ ஒரு கூட்டத்திலிருந்து ஆபத்தை உணர்ந்தால் இதைக் கூறுவார்கள்."),
        "dua_shirk_protection" to DuaText("மறைவான ஷிர்க்கிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! தெரிந்தே உன்னுடன் ஷிர்க் செய்வதிலிருந்து உன்னிடம் பாதுகாப்பு தேடுகிறேன்; அறியாமல் நடந்ததற்கு மன்னிப்பு தேடுகிறேன்.", "காட்டிக் கொடுக்கும் மற்றும் மறைவான ஷிர்க்கிலிருந்து தப்பிக்க.", "மறைவான ஷிர்க் எறும்பின் நடையை விட மறைவானது."),
        "dua_rain" to DuaText("மழை பெய்யும்போது", "யா அல்லாஹ்! பயனுள்ள மழையை அருள்.", "மழை பெய்யும்போது.", "மழை துஆ ஏற்கப்படும் நேரம்."),
        "dua_after_rain" to DuaText("மழைக்குப் பின்", "அல்லாஹ்வின் அருளாலும் கருணையாலும் எங்கள் மீது மழை பெய்தது.", "மழைக்குப் பின்.", "இதைக் கூறுபவன் அல்லாஹ்வில் ஈமான் வைத்தவன்."),
        "dua_istisqa" to DuaText("மழை வேண்டல் (இஸ்திஸ்கா)", "யா அல்லாஹ்! எங்கள் மீது மழை பெய்விடு (மூன்று முறை).", "மழை இல்லாதபோது.", "நபி ﷺ ஜும்ஆ குத்பாவில் இந்த துஆ செய்தார்கள்; மழை பெய்தது."),
        "dua_heavy_rain" to DuaText("அதிக மழை", "யா அல்லாஹ்! எங்கள் சுற்றிலும் (பெய்விடு), எங்கள் மீது அல்ல.", "மழை அதிகமாகிவிட்டால்.", "நபி ﷺ அவர்களின் துஆவால் மேகங்கள் விலகிச் சென்றன."),
        "dua_wind" to DuaText("கடுமையான காற்று வீசும்போது", "யா அல்லாஹ்! இதன் நன்மையையும், இதில் உள்ளதன் நன்மையையும், இது அனுப்பப்பட்ட காரணத்தின் நன்மையையும் தேடுகிறேன்; இதன் தீமையிலிருந்தும், இதில் உள்ளதன் தீமையிலிருந்தும், இது அனுப்பப்பட்ட காரணத்தின் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்பு தேடுகிறேன்.", "கடுமையான காற்று/புயல் வீசும்போது.", "நபி ﷺ புயல் நேரத்தில் இந்த துஆ ஓதுவார்கள்."),
        "dua_thunder" to DuaText("இடி சப்தம் கேட்கும்போது", "அவனுக்கு தஸ்பீஹ் சொல்லும் இடி, அவனுடைய புகழால், மற்றும் வானவர்கள் அவனுக்கான பயத்தால் — தூயவன் அவன்.", "இடி சப்தம் கேட்கும்போது — அப்துல்லாஹ் இப்னு ஜுபைர் (ரலி) அவர்களின் வழக்கம்.", "சூரத்துர் ரஃது (13:13) இலிருந்து."),
        "dua_new_moon" to DuaText("பிறை பார்க்கும்போது", "யா அல்லாஹ்! இந்த பிறையை பாதுகாப்புடன், ஈமானுடன், நலனுடன், இஸ்லாமுடன் எங்கள் மீது உதிக்கச் செய். (பிறையே!) என் இறைவனும் உன் இறைவனும் அல்லாஹ்.", "பிறை பார்க்கும்போது.", "ஒவ்வொரு புதிய மாதத்திலும் சுன்னத்தான துஆ."),
        "dua_janaza_adult" to DuaText("ஜனாஸா நமாஸ் (வயதுவந்தவர்)", "யா அல்லாஹ்! எங்கள் உயிருள்ளவர்கள் மற்றும் இறந்தவர்கள், இருப்பவர்கள் மற்றும் இல்லாதவர்கள், சிறியவர்கள் மற்றும் பெரியவர்கள், ஆண்கள் மற்றும் பெண்கள் அனைவரையும் மன்னி. யா அல்லாஹ்! எங்களில் யாரை உயிருடன் வைக்கிறாயோ அவரை இஸ்லாமில் வாழச் செய், யாருக்கு மரணம் கொடுக்கிறாயோ அவரை ஈமானில் மரணிக்கச் செய்.", "ஜனாஸா நமாஸில் மூன்றாவது தக்பீருக்குப் பின்.", "வயதுவந்தவரின் ஜனாஸாவில் சுன்னத்தான துஆ."),
        "dua_janaza_child" to DuaText("ஜனாஸா நமாஸ் (குழந்தை)", "யா அல்லாஹ்! இவனை எங்களுக்காக முன்செல்பவனாக ஆக்கு, இவனை எங்களுக்கு நன்மை மற்றும் கையிருப்பாக ஆக்கு, இவனை எங்களுக்கு பரிந்துரையாளனாகவும் பரிந்துரை ஏற்கப்பட்டவனாகவும் ஆக்கு.", "சிறு பையனுக்கு ஜனாஸா நமாஸில் (பெண்ணாக இருந்தால் 'இஜ்அல்ஹா').", "ஹனஃபீகளிடம் வழக்கமான சுன்னத்தான துஆ."),
        "dua_mayyit_awf" to DuaText("மையித்துக்கான விரிவான துஆ", "யா அல்லாஹ்! இவரை மன்னி, இவரிடம் கருணை காட்டு, இவரை ஆரோக்கியமாக வைத்திரு, இவரை மன்னி, இவருடைய தங்குமிடத்தை கண்ணியமாக ஆக்கு, இவருடைய மண்ணறையை விசாலமாக்கு, இவரை நீர், பனி, ஆலங்கட்டி மழையால் கழுவு; பாவங்களிலிருந்து இவரை வெள்ளை ஆடை அழுக்கிலிருந்து சுத்தமாவதுபோல் சுத்தமாக்கு.", "ஜனாஸாவில் அல்லது மையித்துக்காக.", "அவ்ஃப் இப்னு மாலிக் (ரலி) இந்த மையித்தாக தாம் இருந்திருந்தால் நலமாயிருந்தது என்று கூறினார்கள்."),
        "dua_visiting_graves" to DuaText("கப்ரிஸ்தான் ஜியாரத்", "ஈமான் கொண்ட மற்றும் முஸ்லிம் வீட்டினரே, உங்களுக்கு சலாம்! இன்ஷா அல்லாஹ் நாங்களும் உங்களிடம் வரவிருக்கிறோம். என்னுடைய மற்றும் உங்களுடைய நலனுக்காக அல்லாஹ்விடம் தேடுகிறேன்.", "கப்ரிஸ்தானில் நுழையும்போது.", "மண்ணறை ஜியாரத் மரணத்தையும் மறுமையையும் நினைவூட்டுகிறது."),
        "dua_closing_eyes" to DuaText("மையித்தின் கண்களை மூடும்போது", "யா அல்லாஹ்! (பெயர்) அவரை மன்னி, நேர்வழி பெற்றவர்களில் அவரின் தரத்தை உயர்த்து, அவருக்கு பின் விடப்பட்டவர்களிடம் அவரை மாற்றாரவாக ஆகிவிடு, எங்களையும் இவரையும் மன்னி ரப்புல் ஆலமீன்!, இவரின் மண்ணறையை விசாலப்படுத்து அதில் ஒளியூட்டு.", "மையித்தின் கண்களை மூடும்போது (பெயர் சொல்லி).", "நபி ﷺ அபூ ஸலமா (ரலி) அவர்களுக்காக இந்த துஆ செய்தார்கள்."),
        "dua_condolence" to DuaText("தாஜியத்", "நிச்சயமாக அல்லாஹ்விடமிருந்ததுதான் — அவன் எடுத்தான்; அவனிடமிருந்ததுதான் அவன் கொடுத்தான்; அவனிடம் எல்லாவற்றுக்கும் நியமிக்கப்பட்ட நேரம் இருக்கிறது. பொறுமை காட்டி நன்மை எதிர்பாருங்கள்.", "ஒருவர் இறந்தால் குடும்பத்தினரிடம் தாஜியத் கூறும்போது.", "நபி ﷺ தன் மகளிடம் இந்த செய்தி அனுப்பினார்கள்."),
        "dua_placing_in_grave" to DuaText("மையித்தை மண்ணறையில் இறக்கும்போது", "அல்லாஹ்வின் பெயரால், ரசூலுல்லாஹ் ﷺ யின் மில்லத்தின் மீது.", "மையித்தை மண்ணறையில் இறக்கும்போது.", "தஃப்னீனின் சுன்னத்தான துஆ."),
        "dua_sneezing" to DuaText("தும்மல் வரும்போது", "எல்லாப் புகழும் அல்லாஹ்வுக்கே. — அல்லாஹ் உங்களுக்கு கருணை காட்டட்டும். — அல்லாஹ் உங்களுக்கு நேர்வழி காட்டட்டும், உங்கள் நிலையை சீர்செய்யட்டும்.", "தும்மல் வந்தால்; கேட்பவர் 'யர்ஹமுகல்லாஹ்' சொல்வார், பின்னர் தும்முபவர் பதிலளிப்பார்.", "முஸ்லிமுக்கு முஸ்லிமின் உரிமைகளில் ஒன்று."),
        "dua_toilet_enter" to DuaText("கழிப்பறையில் நுழையும்போது", "அல்லாஹ்வின் பெயரால். யா அல்லாஹ்! அபவித்திரமான ஜின்களிலிருந்து (ஆண் மற்றும் பெண்) உன்னிடம் பாதுகாப்பு தேடுகிறேன்.", "கழிப்பறையில் இடது கால் வைப்பதற்கு முன்.", "பிஸ்மில்லாஹ் ஜின்னாத்திற்கும் மனிதருக்கும் மறைப்பாகிறது."),
        "dua_toilet_exit" to DuaText("கழிப்பறையிலிருந்து வெளியேறும்போது", "(யா அல்லாஹ்!) உன்னிடம் மன்னிப்பு தேடுகிறேன்.", "கழிப்பறையிலிருந்து வலது கால் வெளியே வைக்கும்போது.", "நபி ﷺ கழிப்பறையிலிருந்து வெளியே வந்தால் இதைக் கூறுவார்கள்."),
        "dua_thanking" to DuaText("யாரையாவது நன்றி சொல்வது", "அல்லாஹ் உங்களுக்கு சிறந்த பரிசு தரட்டும்.", "யாரோ உதவி செய்தால்.", "இதைக் கூறியவர் புகழுக்கு உரிய உரிமை அடைந்தார்."),
        "dua_love_for_allah" to DuaText("யாரோ 'அல்லாஹ்வின் பொருட்டு உங்களை நேசிக்கிறேன்' என்று கூறும்போது", "அதற்காக நீங்கள் என்னை நேசித்தவனான (அல்லாஹ்) உங்களை நேசிக்கட்டும்.", "யாரோ 'அல்லாஹ்வின் பொருட்டு உங்களை நேசிக்கிறேன்' என்று கூறும்போது.", "அல்லாஹ்வின் பொருட்டு நேசத்திற்கான சுன்னத்தான பதில் துஆ."),
        "dua_seeing_muslim_smile" to DuaText("சலாம்", "உங்கள் மீது சலாமதும், அல்லாஹ்வின் கருணையும், அவனது பரக்கத்தும் இருக்கட்டும்.", "முஸ்லிமை சந்திக்கும்போது.", "முழுமையான சலாம் கூறுவதால் முப்பது நன்மைகள் கிடைக்கும்."),
        "dua_dressing" to DuaText("உடை அணியும்போது", "எல்லாப் புகழும் அல்லாஹ்வுக்கே — அவன் என்னை இந்த உடை அணிவித்தான், என் எந்த சக்தியும் ஆற்றலும் இல்லாமல் இதை அருளினான்.", "உடை அணியும்போது.", "முந்தைய பாவங்கள் மன்னிக்கப்படும் என்ற நற்செய்தி."),
        "dua_rooster_donkey" to DuaText("சேவல் அல்லது கழுதையின் சப்தம் கேட்கும்போது", "யா அல்லாஹ்! உன் அருளை தேடுகிறேன் (சேவல்). — ஆட்டப்பட்ட ஷைத்தானிடமிருந்து அல்லாஹ்விடம் பாதுகாப்பு தேடுகிறேன் (கழுதை).", "சேவல் கூவும்போது அல்லாஹ்வின் அருளை தேடுங்கள்; கழுதை கத்தும்போது ஷைத்தானிடமிருந்து பாதுகாப்பு.", "சேவல் வானவரை பார்க்கிறது; கழுதை ஷைத்தானை பார்க்கிறது."),
        "dua_something_liked" to DuaText("விரும்பியதை பார்க்கும்போது (பொல்லாட்டிலிருந்து பாதுகாப்பு)", "அல்லாஹ் நாடியது. யா அல்லாஹ்! இதில் பரக்கத் தருவாயாக.", "யாரின் நல்ல பொருளை பார்க்கும்போது பரக்கத் துஆ கூறுங்கள்.", "பரக்கத் துஆ கூறுவதால் பொல்லாட்டு படாது."),
        "dua_sell_buy_debt_repaid" to DuaText("கடன் திருப்பிக் கொடுக்கும்போது", "அல்லாஹ் உங்கள் குடும்பத்திலும் செல்வத்திலும் பரக்கத் அளிக்கட்டும்.", "கடன் திருப்பிக் கொடுக்கும்போது கடன் கொடுத்தவருக்காக.", "கடனுக்கான பரிசு நன்றியும் திருப்பிக் கொடுப்பதும்."),
        "dua_talbiyah" to DuaText("தல்பியா", "நான் ஹாஜிராக இருக்கிறேன், யா அல்லாஹ் நான் ஹாஜிராக இருக்கிறேன். நான் ஹாஜிராக இருக்கிறேன், உனக்கு எந்த இணையுமில்லை, நான் ஹாஜிராக இருக்கிறேன். நிச்சயமாக எல்லாப் புகழும், நன்மையும், ஆட்சியும் உனக்கே, உனக்கு எந்த இணையுமில்லை.", "இஹ்ராம் கட்டிய பின் உரக்கக் கூறுதல்.", "ஹஜ் மற்றும் உம்ராவின் குறிக்கோள்."),
        "dua_yamani_hajar" to DuaText("ருக்னுல் யமானி மற்றும் ஹஜருல் அஸ்வத்திற்கு இடையில்", "எங்கள் இறைவா! உலகிலும் நன்மை கொடு, மறுமையிலும் நன்மை கொடு, நரக வேதனையிலிருந்து காப்பாற்று.", "தவாஃபில் ருக்னுல் யமானிக்கும் ஹஜருல் அஸ்வத்திற்கும் இடையில்.", "நபி ﷺ தவாஃபில் இந்த இடத்தில் இதை ஓதுவார்கள்."),
        "dua_safa_marwa" to DuaText("ஸஃபா மற்றும் மர்வாவில்", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணையில்லை, ஆட்சியும் புகழும் அவனுக்கே, அவன் எல்லாவற்றின் மீதும் ஆற்றல் கொண்டவன். அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், தன் வாக்கை நிறைவேற்றினான், தன் அடியானுக்கு உதவி செய்தான், தனியாக எல்லா படைகளையும் தோற்கடித்தான்.", "ஸஃபாவில் கிப்லா நோக்கி நின்று (மூன்று முறை).", "நபி ﷺ ஸஃபா மற்றும் மர்வாவில் ஜிக்ர்."),
        "dua_arafah" to DuaText("அரஃபாவின் நாள் சிறந்த துஆ", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணையில்லை, ஆட்சியும் புகழும் அவனுக்கே, அவன் எல்லாவற்றின் மீதும் ஆற்றல் கொண்டவன்.", "யவ்முல் அரஃபா — சிறந்த துஆ.", "சிறந்த துஆ அரஃபாவின் நாள் துஆவாகும்; சிறந்த கலிமா இதுவே."),
        "dua_takbeer_tashreeq" to DuaText("தக்பீர் தஷ்ரீக்", "அல்லாஹு அக்பர், அல்லாஹு அக்பர். அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை. அல்லாஹு அக்பர், அல்லாஹு அக்பர், எல்லாப் புகழும் அல்லாஹ்வுக்கே.", "9 ஜுல்ஹிஜ்ஜா ஃபஜ்ரிலிருந்து 13 அஸர் வரை ஒவ்வொரு ஃபர்ஜ் நமாஸுக்குப் பின்.", "அலீ மற்றும் இப்னு மஸ்ஊத் (ரலி) அவர்களிடமிருந்து — ஹனஃபீகளிடம் வாஜிப்."),
        "dua_zamzam" to DuaText("ஜம்ஜம் குடிக்கும்போது", "யா அல்லாஹ்! பயனுள்ள அறிவையும், விசாலமான ரிஸ்கையும், எல்லா நோய்களிலிருந்தும் ஷிஃபாவையும் தேடுகிறேன்.", "ஜம்ஜம் குடிக்கும்போது நினைவில் வைத்திருக்கும் நிய்யத்தை துஆ கொண்டு கேளுங்கள்.", "ஜம்ஜம் எந்த நிய்யத்தால் குடிக்கப்படுகிறதோ அதற்காகவே (இப்னு மாஜா 3062)."),
        "dua_q_ma_khalaqta_batila" to DuaText("படைப்பை சிந்திக்கும்போது", "எங்கள் இறைவா! நீ இதை வீணாக படைக்கவில்லை, தூயவன் நீ, நரக வேதனையிலிருந்து எங்களை காப்பாற்று.", "வானங்களின் மற்றும் பூமியின் படைப்பை சிந்திக்கும் பேரறிவாளர்களின் துஆ.", "உலுல் அல்பாப் (பேரறிவாளர்கள்) துஆ."),
        "dua_q_sami_na_munadiyan" to DuaText("நாங்கள் ஈமானிற்கு அழைத்த குரலைக் கேட்டோம்", "எங்கள் இறைவா! 'உங்கள் இறைவனில் ஈமான் வாருங்கள்' என்று ஈமானிற்கு அழைக்கும் ஒரு குரலை கேட்டோம்; நாங்கள் ஈமான் வந்தோம். எங்கள் பாவங்களை மன்னி, எங்கள் தீமைகளை நீக்கு, நேர்மையானவர்களுடன் எங்களுக்கு மரணம் தரு.", "ஈமான் மற்றும் நேர்மையானவர்களுடன் மரணத்திற்கான துஆ.", "மன்னிப்பு மற்றும் ஹுஸ்னுல் ஖ாதிமா துஆ."),
        "dua_q_atina_ma_waadtana" to DuaText("நீ வாக்களித்ததை தருவாயாக", "எங்கள் இறைவா! உன் ரசூல்கள் மூலம் வாக்களித்ததை எங்களுக்கு தருவாயாக; மறுமை நாளில் எங்களை இழிவுபடுத்தாதே, நிச்சயமாக நீ வாக்கை மீறுவதில்லை.", "மறுமையில் இழிவில் வீழ்வதிலிருந்து பாதுகாப்பு.", "மறுமையில் மதிப்பை தேடுதல்."),
        "dua_q_israfana" to DuaText("எங்கள் அதிகப்படியான செயல்களை மன்னி", "எங்கள் இறைவா! எங்கள் பாவங்களையும் எங்கள் செயல்களில் எங்கள் அதிகப்படியான நடத்தையையும் மன்னி, எங்கள் அடிகளை உறுதிப்படுத்து, காஃபிர் கூட்டத்திற்கு எதிராக எங்களுக்கு உதவி செய்.", "முந்தைய நபிமார்களின் தோழர்களின் துஆ.", "உறுதி மற்றும் மன்னிப்புக்கான துஆ."),
        "dua_q_jamiun_nas" to DuaText("நீ மக்களை ஒன்று சேர்ப்பவன்", "எங்கள் இறைவா! நிச்சயமாக நீ சந்தேகமில்லாத ஒரு நாளில் மக்களை ஒன்று சேர்ப்பவன். நிச்சயமாக அல்லாஹ் வாக்கை மீறுவதில்லை.", "மறுமையில் நம்பிக்கையை ஒப்புக்கொள்ளல்.", "அறிவில் உறுதியானவர்களின் துஆ."),
        "dua_q_maash_shahidin" to DuaText("சாட்சியர்களில் எங்களை எழுது", "எங்கள் இறைவா! நாங்கள் ஈமான் வந்தோம்; சாட்சியர்களுடன் எங்களை எழுது.", "உண்மையை அறிந்து ஈமான் வந்தவர்களின் துஆ.", "ஈமான் ஏற்கப்படுவதற்கான துஆ."),
        "dua_q_la_tajalna_zalimin" to DuaText("அக்கிரமக்காரர்களுடன் எங்களை வைக்காதே", "எங்கள் இறைவா! அக்கிரமக்காரர்களுடன் எங்களை வைக்காதே.", "அஸ்ஹாபுல் அஃராஃபின் துஆ.", "அக்கிரமக்காரர்களின் முடிவிலிருந்து பாதுகாப்பு."),
        "dua_q_tawaffana_muslimin" to DuaText("பொறுமை மற்றும் முஸ்லிமாய் மரணம்", "எங்கள் இறைவா! எங்கள் மீது பொறுமை பொழி, முஸ்லிம்களாய் மரணிக்கச் செய்.", "ஈமான் வந்த ஃபிர்அவ்னின் சூத்திரக்காரர்களின் துஆ.", "சோதனையில் பொறுமை மற்றும் ஈமானில் முடிவு."),
        "dua_q_la_tajalna_fitnah" to DuaText("அக்கிரமக்காரர்களுக்கான சோதனையாக ஆக்காதே", "அல்லாஹ்வில் நம்பிக்கை வைத்தோம். எங்கள் இறைவா! அக்கிரமக்கார கூட்டத்திற்கான சோதனையாக எங்களை ஆக்காதே; உன் கருணையால் காஃபிர் கூட்டத்திலிருந்து எங்களை காப்பாற்று.", "மூஸா (அலை) அவர்களின் கூட்டத்தினரின் துஆ.", "ஒடுக்கல் மற்றும் அக்கிரமக்காரர்களிலிருந்து காப்பாற்றல்."),
        "dua_q_nuh_ma_laysa_li" to DuaText("மன்னிப்புக்காக நூஹ் (அலை) துஆ", "என் இறைவா! அறியாத ஒன்றை உன்னிடம் கேட்பதிலிருந்து உன்னிடம் பாதுகாப்பு தேடுகிறேன். நீ என்னை மன்னிக்கவில்லை என்றால், எனக்கு கருணை காட்டவில்லை என்றால், நான் இழப்பவர்களில் ஆவேன்.", "நூஹ் (அலை) அவர்களின் தவ்பா துஆ.", "பணிவோடு துஆ கேட்பதன் கல்வி."),
        "dua_q_mudkhala_sidq" to DuaText("உண்மையோடு நுழைவதும் வெளியேறுவதும்", "என் இறைவா! என்னை உண்மையோடு நுழைய வை, உண்மையோடு வெளியேறச் செய், உன்னிடமிருந்து உதவும் ஆதிக்கத்தை எனக்கு அளி.", "எந்த புதிய செயல், வீடு அல்லது இடத்தில் நுழைவதற்கு முன்.", "ஹிஜ்ரத் சந்தர்ப்பத்தில் நபி ﷺ க்கு கற்பிக்கப்பட்ட துஆ."),
        "dua_q_la_tadharni_fardan" to DuaText("என்னை தனியாக விடாதே (ஜக்கரிய்யா அலை)", "என் இறைவா! என்னை தனியாக விடாதே; நீ சிறந்த வாரிசு.", "சந்தானத்திற்கான வேண்டுதல்.", "இந்த துஆவுக்கு அல்லாஹ் யஹ்யா (அலை) அவர்களை அருளினான்."),
        "dua_q_munzalan_mubarakan" to DuaText("பரக்கத் நிறைந்த இடத்தில் இறக்குவாயாக", "என் இறைவா! என்னை பரக்கத் நிறைந்த இடத்தில் இறக்கு; நீ சிறந்த இறக்குபவன்.", "புதிய வீட்டிற்கு குடி புகும்போது — நூஹ் (அலை) துஆ.", "புதிய இடத்தில் பரக்கத் கோரும் துஆ."),
        "dua_q_amanna_faghfir" to DuaText("நாங்கள் ஈமான் வந்தோம், மன்னிப்பாயாக", "எங்கள் இறைவா! நாங்கள் ஈமான் வந்தோம், மன்னிப்பாயாக, கருணை காட்டுவாயாக; நீ கருணையாளர்களில் சிறந்தவன்.", "அல்லாஹ்வின் நல்ல அடியார்களின் துஆ.", "மன்னிப்பும் கருணையும் கோரும் விரிவான துஆ."),
        "dua_q_isrif_jahannam" to DuaText("நரக வேதனையை திருப்பு", "எங்கள் இறைவா! நரக வேதனையை எங்களிலிருந்து திருப்பு; நிச்சயமாக அதன் வேதனை ஒட்டிக்கொள்வதாகும். நிச்சயமாக அது கெட்ட இருப்பிடம், கெட்ட தங்குமிடம்.", "இபாதுர் ரஹ்மான் (கருணையாளனின் அடியார்கள்) துஆ.", "நரகத்திலிருந்து பாதுகாப்புக்கான குர்ஆனிய துஆ."),
        "dua_q_hab_li_hukman" to DuaText("ஞானமும் சொர்க்கமும் (இப்ராஹீம் அலை)", "என் இறைவா! ஞானம் தருவாயாக, நேர்மையானவர்களுடன் சேர்ப்பாயாக, பிற்பாடு வருவோரிடம் என்னை நன்மையாக நினைக்கும்படி வை, நன்மைகள் நிறைந்த சொர்க்கத்தின் வாரிசுகளில் ஒருவனாக ஆக்கு.", "ஞானம், நேர்மையானவர்களின் நட்பு, சொர்க்கம் தேடல்.", "இப்ராஹீம் (அலை) அவர்களின் விரிவான துஆ."),
        "dua_q_lut_najjini_ahli" to DuaText("என் குடும்பத்தை காப்பாற்று (லூத் அலை)", "என் இறைவா! அவர்களின் செயல்களிலிருந்து என்னையும் என் குடும்பத்தையும் காப்பாற்று.", "தீய சூழலிலிருந்து குடும்பத்தை பாதுகாத்தல்.", "தீமையிலிருந்து குடும்பத்தை பாதுகாத்தல்."),
        "dua_q_sulaiman_awzini" to DuaText("நன்றி கூறுவதற்கு சுலைமான் (அலை) துஆ", "என் இறைவா! எனக்கும் என் பெற்றோருக்கும் அளித்த உன் நன்மைகளுக்கு நன்றி கூறவும், நீ விரும்பும் நல்ல செயல் செய்யவும் எனக்கு அனுமதி தருவாயாக; உன் கருணையால் நன்மையான அடியார்களில் என்னை சேர்ப்பாயாக.", "நன்மைக்கு நன்றி கூறுவதற்கான அனுமதி.", "சுலைமான் (அலை) அவர்களின் நன்றி துஆ."),
        "dua_q_musa_zalamtu" to DuaText("என் ஆத்மாவிற்கு அநியாயம் செய்தேன் (மூஸா அலை)", "என் இறைவா! என் ஆத்மாவிற்கு அநியாயம் செய்தேன்; என்னை மன்னிப்பாயாக.", "தவறு நடந்தவுடன் உடனடியாக தவ்பா.", "அல்லாஹ் மூஸா (அலை) அவர்களை மன்னித்தான்."),
        "dua_q_musa_najjini" to DuaText("அக்கிரமக்காரர்களிலிருந்து காப்பாற்று (மூஸா அலை)", "என் இறைவா! அக்கிரமக்கார கூட்டத்திலிருந்து என்னை காப்பாற்று.", "அக்கிரமக்காரர்களின் பயத்தில்.", "எகிப்திலிருந்து வெளியேறும்போது மூஸா (அலை) அவர்களின் துஆ."),
        "dua_q_lut_unsurni" to DuaText("கலகக்காரர்களுக்கு எதிராக உதவி (லூத் அலை)", "என் இறைவா! கலகக்காரர் கூட்டத்திற்கு எதிராக என்னுக்கு உதவி செய்.", "கலகக்காரர்களுக்கு எதிராக உதவி.", "உண்மையில் உறுதியாக இருப்பவர்களின் துஆ."),
        "dua_q_hab_li_salihin" to DuaText("நல்ல சந்தானத்திற்காக இப்ராஹீம் (அலை) துஆ", "என் இறைவா! (சந்தானத்திலிருந்து) நல்லவர்களை எனக்கு அருள்.", "நல்ல சந்தானம் தேடல்.", "இந்த துஆவுக்கு இஸ்மாஈல் (அலை) அருளப்பட்டனர்."),
        "dua_q_wasita_kulla_shay" to DuaText("அர்ஷை தூக்கும் வானவர்களின் துஆ", "எங்கள் இறைவா! உன் கருணையும் அறிவும் எல்லாவற்றையும் சூழ்ந்துகொண்டது; தவ்பா செய்து உன் வழியில் நடந்தவர்களை மன்னி, நரக வேதனையிலிருந்து அவர்களை காப்பாற்று.", "அர்ஷை தூக்கும் வானவர்கள் மோமின்களுக்காக இந்த துஆ செய்கிறார்கள்.", "வானவர்களின் துஆவில் சேரும் நினைவோடு."),
        "dua_q_ikhwanina" to DuaText("எங்களுக்கு முன் வந்த சகோதரர்களுக்காக", "எங்கள் இறைவா! எங்களையும் ஈமான் கொண்டு எங்களுக்கு முன் வந்த சகோதரர்களையும் மன்னி; ஈமான் கொண்டவர்களிடம் எங்கள் இதயத்தில் வெறுப்பை வைக்காதே. எங்கள் இறைவா! நிச்சயமாக நீ கருணையுடையவன், மிகவும் கருணையாளன்.", "முந்தைய மோமின்களுக்காகவும் இதயத்தை சுத்தப்படுத்தவும்.", "ஸஹாபா கிராம் (ரலி) மற்றும் முந்தைய மோமின்களுக்காக துஆ."),
        "dua_q_alayka_tawakkalna" to DuaText("உன்னில் நம்பிக்கை வைத்தோம் (இப்ராஹீம் அலை)", "எங்கள் இறைவா! உன்னில் நம்பிக்கை வைத்தோம், உன்னை நோக்கி திரும்பினோம், உன்னிடமே மீளுதல். எங்கள் இறைவா! காஃபிர்களுக்கான சோதனையாக ஆக்காதே, மன்னிப்பாயாக. எங்கள் இறைவா! நிச்சயமாக நீ வல்லவன், ஞானமுடையவன்.", "இப்ராஹீம் (அலை) மற்றும் அவர்களின் தோழர்களின் துஆ.", "தவக்கல் மற்றும் திரும்புதலின் துஆ."),
        "dua_q_atmim_nurana" to DuaText("எங்கள் ஒளியை முழுமையாக்கு", "எங்கள் இறைவா! எங்கள் ஒளியை நிறைவுசெய், எங்களை மன்னி; நிச்சயமாக நீ எல்லாவற்றின் மீதும் ஆற்றல் கொண்டவன்.", "மறுமையில் மோமின்களின் துஆ.", "புல்ஸிராத்தில் ஒளி தேடல்."),
        "dua_q_asiya_baytan" to DuaText("சொர்க்கத்தில் வீடு (ஆஸியா)", "என் இறைவா! என்னுக்காக உன்னிடம் சொர்க்கத்தில் வீடு கட்டுவாயாக; ஃபிர்அவ்னிடமிருந்தும் அவனது செயல்களிலிருந்தும் என்னை காப்பாற்று, அக்கிரமக்கார கூட்டத்திலிருந்தும் காப்பாற்று.", "ஃபிர்அவ்னின் மனைவி ஆஸியாவின் துஆ.", "அல்லாஹ் அவர்களை மோமின்களுக்கு எடுத்துக்காட்டாக ஆக்கினான்."),
        "dua_adhan_response" to DuaText("அதானுக்கு பதிலளிக்கல்", "அல்லாஹ்வில்லாமல் எந்த சக்தியும் ஆற்றலும் இல்லை.", "முஅத்தின் சொல்வதை திரும்பி சொல்லுங்கள்; 'ஹய்யா அலஸ்ஸலாஹ்' மற்றும் 'ஹய்யா அலலல்ஃபலாஹ்'க்கு இதைக் கூறுங்கள்.", "இதயமார பதில் சொல்பவர் சொர்க்கத்தில் நுழைவார்."),
        "dua_adhan_shahadah" to DuaText("முஅத்தினின் ஷஹாதத்துக்குப் பின்", "நானும் சாட்சியமளிக்கிறேன் — அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணையில்லை; முஹம்மத் ﷺ அவனது அடியான் மற்றும் ரசூல். அல்லாஹ் இறைவனாகவும், முஹம்மத் ﷺ ரசூலாகவும், இஸ்லாம் தீனாகவும் இருப்பதில் திருப்தியடைந்தேன்.", "முஆத்தினின் ஷஹாததைனை கேட்கும்போது.", "அவரின் பாவங்கள் மன்னிக்கப்படும்."),
        "dua_istiftah_baid" to DuaText("தொடக்க துஆ: பாவங்களிலிருந்து என்னை விலக்கு", "யா அல்லாஹ்! என்னுக்கும் என் பாவங்களுக்கும் இடையில் கிழக்கும் மேற்கும் விலக்கியதுபோல் விலக்கு. யா அல்லாஹ்! பாவங்களிலிருந்து என்னை வெண்மையான ஆடையை அழுக்கிலிருந்து சுத்தமாக்குவதுபோல் சுத்தமாக்கு. யா அல்லாஹ்! என் பாவங்களை தண்ணீர், பனி, ஆலங்கட்டியால் கழுவு.", "தக்பீரத்துல் இஹ்ராமுக்குப் பின் (ஸனாவுக்கு பதிலாகவும் ஓதலாம்).", "நபி ﷺ தக்பீர் மற்றும் கிராஆத்திற்கு இடையில் இதை ஓதுவார்கள்."),
        "dua_hamdan_kathiran" to DuaText("ருகூஃவுக்குப் பின் மிகவும் அதிகமான புகழ்", "எங்கள் இறைவா! உனக்கே புகழ் — மிகவும் அதிகமாக, தூய்மையான, பரக்கத்தான புகழ்.", "ருகூஃவிலிருந்து எழுந்த பின் 'ரப்பனா லகல்ஹம்த்'உடன்.", "முப்பதுக்கும் அதிகமான வானவர்கள் இதை முதலில் எழுத போட்டியிட்டனர்."),
        "dua_subbuhun_quddus" to DuaText("ஸுப்பூஹுன் குத்துஸ் (ருகூஃ மற்றும் ஸஜ்தா)", "(அல்லாஹ்) மிகவும் தூயவன், மிகவும் மூக்கடஸ், வானவர்கள் மற்றும் ரூஹ் (ஜிப்ரீல்) இன் இறைவன்.", "ருகூஃ மற்றும் ஸஜ்தாவில்.", "நபி ﷺ ருகூஃ மற்றும் ஸஜ்தாவில் இதை ஓதுவார்கள்."),
        "dua_sujood_dhanbi_kullah" to DuaText("ஸஜ்தாவில்: என் எல்லா பாவங்களையும் மன்னி", "யா அல்லாஹ்! என் எல்லா பாவங்களையும் மன்னிப்பாயாக — சிறியதும் பெரியதும், முந்தினதும் பிந்தினதும், வெளிப்படையும் மறைவானதும்.", "ஸஜ்தாவில்.", "ஸஜ்தா துஆ ஏற்கப்படும் இடம்."),
        "dua_sujood_ridaka" to DuaText("உன் திருப்தியில் பாதுகாப்பு", "யா அல்லாஹ்! உன் திருப்தி கொண்டு உன் கோபத்திலிருந்தும், உன் மன்னிப்பு கொண்டு உன் தண்டனையிலிருந்தும் பாதுகாப்பு தேடுகிறேன், உன்னிடமிருந்தே பாதுகாப்பு தேடுகிறேன். உன் புகழை முழுமையாக செய்ய என்னால் இயலாது, நீ உன்னையே புகழ்ந்தவாறே இருக்கிறாய்.", "ஸஜ்தாவில் — ஆயிஷா (ரலி) நபி ﷺ இதை ஓதுவதைக் கேட்டனர்.", "நபி ﷺ அவர்களின் ஸஜ்தா துஆ."),
        "dua_tashahhud" to DuaText("தஷஹ்ஹுத் (அத்தஹிய்யாத்)", "வாய்மொழி, உடல் மற்றும் செல்வ இபாதத்கள் அல்லாஹ்வுக்கே. ஓ நபியே! உங்கள் மீது சலாமும், அல்லாஹ்வின் கருணையும் அவனது பரக்கத்தும் இருக்கட்டும். எங்கள் மீதும் அல்லாஹ்வின் நல்ல அடியார்கள் மீதும் சலாம் இருக்கட்டும். அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை என்று சாட்சியமளிக்கிறேன், முஹம்மத் ﷺ அவனது அடியான் மற்றும் ரசூல் என்று சாட்சியமளிக்கிறேன்.", "ஒவ்வொரு கஃதாவிலும் — அப்துல்லாஹ் இப்னு மஸ்ஊத் (ரலி) அவர்களின் ரிவாயத் (ஹனஃபீகளின் வழக்கம்).", "நபி ﷺ இதை குர்ஆன் சூராவுபோல் கற்றுக் கொடுப்பார்கள்."),
        "dua_sajdah_tilawah" to DuaText("ஸஜ்தா திலாவத்", "என் முகம் தன்னை படைத்தவனுக்கு ஸஜ்தா செய்தது — அவனது சக்தி மற்றும் ஆற்றலால் அதற்கு காதும் கண்ணும் ஏற்படுத்தியவனுக்கு.", "ஸஜ்தா திலாவத்தில்.", "நபி ﷺ இரவு ஸஜ்தா திலாவத்தில் இதை ஓதுவார்கள்."),
        "dua_after_witr" to DuaText("வித்ருக்குப் பின்", "மன்னன் தூயவன், மிகவும் மூக்கடஸ்.", "வித்ர் ஸலாமுக்குப் பின் மூன்று முறை; மூன்றாம் முறை குரலை உயர்த்தி.", "நபி ﷺ வித்ருக்குப் பின் இதைக் கூறுவார்கள்."),
        "dua_tahajjud_nur" to DuaText("தஹஜ்ஜுத் தொடக்க துஆ", "யா அல்லாஹ்! உனக்கே புகழ், நீ வானங்கள், பூமி மற்றும் அவற்றிலுள்ளவை அனைத்தையும் நிலை நிறுத்துகிறாய். உனக்கே புகழ், நீ வானங்கள், பூமி மற்றும் அவற்றிலுள்ளவற்றின் ஒளி. உனக்கே புகழ், நீ உண்மை, உன் வாக்கு உண்மை, உன் சந்திப்பு உண்மை, உன் சொல் உண்மை, சொர்க்கம் உண்மை, நரகம் உண்மை, நபிமார்கள் உண்மை, முஹம்மத் ﷺ உண்மை, மறுமை உண்மை.", "இரவு நமாஸ் (தஹஜ்ஜுத்) தொடங்கும்போது (துஆவின் ஆரம்ப பகுதி).", "நபி ﷺ தஹஜ்ஜுத்திற்காக எழுந்தால் இதை ஓதுவார்கள் (முழு துஆ புகாரியில்)."),
        "dua_rabba_jibrail" to DuaText("கருத்து வேறுபாட்டில் வழிகாட்டல்", "யா அல்லாஹ், ஜிப்ரீல், மீகாஈல், இஸ்ராஃபீல் இறைவனே, வானங்கள் மற்றும் பூமி படைத்தவனே, மறைவானதும் வெளிப்படையானதும் அறிந்தவனே! நீ உன் அடியார்கள் கருத்து வேறுபட்ட விஷயங்களில் தீர்ப்பளிப்பாய். தர்க்கமான உண்மையில் உன் கட்டளையால் என்னை வழிகாட்டு. நிச்சயமாக நீ விரும்பியவரை நேர்வழியில் வழிகாட்டுகிறாய்.", "தஹஜ்ஜுத் தொடக்கத்தில் — கருத்து வேறுபாட்டில் உண்மைக்கான வழிகாட்டல்.", "நபி ﷺ இரவு நமாஸை இந்த துஆவிலிருந்து தொடங்குவார்கள்."),
        "dua_going_to_mosque_nur" to DuaText("பள்ளிவாசலுக்கு செல்லும்போது (நூரின் துஆ)", "யா அல்லாஹ்! என் இதயத்தில் ஒளியூட்டு, என் கண்களில் ஒளி, என் காதுகளில் ஒளி, என் வலதில் ஒளி, என் இடதில் ஒளி, என் மேலே ஒளி, என் கீழே ஒளி, என் முன்னே ஒளி, என் பின்னே ஒளி, என்னுக்கு ஒளியாக ஆக்கு.", "ஃபஜ்ரிற்கு பள்ளிவாசலுக்கு செல்லும்போது.", "நபி ﷺ நமாஸுக்கு வெளியேறும்போது இதை ஓதுவார்கள்."),
        "dua_waswasa_salah" to DuaText("நமாஸில் வஸ்வாஸ் (ஹிஞ்ஜிப்)", "ஆட்டப்பட்ட ஷைத்தானிடமிருந்து அல்லாஹ்விடம் பாதுகாப்பு தேடுகிறேன்.", "நமாஸில் ஷைத்தானிய வஸ்வாஸ் வந்தால் பாதுகாப்பு தேடி இடது பக்கம் மூன்று முறை லேசாக துப்புங்கள்.", "உஸ்மான் இப்னு அபீல் ஆஸ் (ரலி) இதைச் செய்து வஸ்வாஸ் சென்றது."),
        "dua_alimal_ghayb" to DuaText("மறைவானதை அறிந்தவன்", "யா அல்லாஹ், மறைவானதும் வெளிப்படையானதும் அறிந்தவனே, வானங்கள் மற்றும் பூமி படைத்தவனே, எல்லாவற்றின் இறைவன் மற்றும் உரிமையாளனே! நீ அல்லாஹ் என்று சாட்சியமளிக்கிறேன், உன்னைத் தவிர வணக்கத்திற்குரியவன் இல்லை. என் ஆத்மாவின் தீங்கிலிருந்தும் ஷைத்தானின் தீங்கிலிருந்தும் அவனது ஷிர்க்கிலிருந்தும் உன்னிடம் பாதுகாப்பு தேடுகிறேன்.", "காலை, மாலை, தூங்குவதற்கு முன் — நபி ﷺ அபூ பக்ர் (ரலி) அவர்களுக்கு கற்பித்தது.", "ஆத்மா மற்றும் ஷைத்தானின் தீங்கிலிருந்து பாதுகாப்பு."),
        "dua_fitratil_islam" to DuaText("இஸ்லாமின் ஃபித்ராவில்", "இஸ்லாமின் ஃபித்ராவில், கலிமா இஹ்லாஸில், நபி முஹம்மத் ﷺ அவர்களின் தீனில், ஏகத்துவமான ஆப்ரஹாமிய மில்லத்தில் காலையை வரவேற்கிறோம் — அவர்கள் ஹனீஃபாய் இருந்தனர், முஷ்ரிக்குகளில் இல்லாதவர்கள்.", "காலை வேளையில்.", "ஒவ்வொரு காலையும் ஈமானை புதுப்பித்தல்."),
        "dua_amsayna_fitrah" to DuaText("மாலையில் இஸ்லாமின் ஃபித்ராவில்", "இஸ்லாமின் ஃபித்ராவில், கலிமா இஹ்லாஸில், நபி முஹம்மத் ﷺ அவர்களின் தீனில், ஏகத்துவமான ஆப்ரஹாமிய மில்லத்தில் மாலையை வரவேற்கிறோம் — அவர்கள் ஹனீஃபாய் இருந்தனர், முஷ்ரிக்குகளில் இல்லாதவர்கள்.", "மாலை வேளையில்.", "ஒவ்வொரு மாலையும் ஈமானை புதுப்பித்தல்."),
        "dua_tahleel_10_fajr" to DuaText("ஃபஜ்ர் மற்றும் மஃரிபுக்குப் பின் பத்து முறை தஹ்லீல்", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணையில்லை, ஆட்சியும் புகழும் அவனுக்கே, அவனே உயிர் கொடுக்கிறான் மற்றும் இறப்பிக்கிறான், அவன் எல்லாவற்றின் மீதும் ஆற்றல் கொண்டவன்.", "ஃபஜ்ர் (மற்றும் மஃரிப்)க்குப் பின், கால்கள் மடக்கியும் பேசாமலும் பத்து முறை.", "பத்து நன்மைகள், பத்து பாவங்கள் மன்னிப்பு, பத்து தரப்படல், நாள் முழுவதும் ஷைத்தானிடமிருந்து பாதுகாப்பு."),
        "dua_la_hawla_kanz" to DuaText("சொர்க்கத்தின் கஜானா", "அல்லாஹ்வில்லாமல் எந்த சக்தியும் ஆற்றலும் இல்லை.", "எப்போதும் அதிகமாக.", "இது சொர்க்கத்தின் கஜானாகளில் ஒன்று."),
        "dua_four_beloved_words" to DuaText("அல்லாஹ்வுக்கு மிகவும் பிரியமான நான்கு கலிமாக்கள்", "அல்லாஹ் தூயவன், எல்லாப் புகழும் அல்லாஹ்வுக்கே, அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அல்லாஹ் மிகவும் பெரியவன்.", "அல்லாஹ்வுக்கு மிகவும் பிரியமான கலிமாக்கள்.", "நபி ﷺ க்கு சூரியன் உதிக்கும் எல்லாவற்றை விட இவை மிகவும் பிரியமானவை."),
        "dua_two_light_words" to DuaText("நாவில் இலகுவான இரண்டு கலிமாக்கள்", "அல்லாஹ் தன் புகழுடன் தூயவன், மஹாமேன்மையான அல்லாஹ் தூயவன்.", "நாவில் இலகு, மீஜானில் கனமுடையவை.", "ரஹ்மானுக்கு பிரியமானவை, நாவில் இலகு, மீஜானில் கனம். (புகாரியின் கடைசி ஹதீஸ்)"),
        "dua_ya_dhal_jalal" to DuaText("யா தல்ஜலாலி வல்இக்ராம்", "மாட்சிமையும் கண்ணியமும் உடையவனே!", "துஆவில் இதை ஒட்டிக்கொள்ளுங்கள் — நபி ﷺ அவர்களின் கட்டளை.", "நபி ﷺ கூறினார்: 'யா தல்ஜலாலி வல்இக்ராம்' ஒட்டிக்கொள்ளுங்கள்."),
        "dua_sleep_wadatu_janbi" to DuaText("உன் பெயரில் என் பக்கத்தை வைத்தேன்", "என் இறைவா! உன் பெயரில் என் பக்கத்தை வைத்தேன், உன் பெயரிலேயே எழுவேன். என் ஆத்மாவை தடுத்தால் கருணை காட்டு, விட்டால் நல்லடியார்களை காப்பாற்றுவதுபோல் காப்பாற்று.", "படுக்கையை தட்டி துப்பட்டி போட்டுக்கொண்டு படுத்தப் பின்.", "தூங்குவதற்கு முன் ஆத்மாவை அல்லாஹ்விடம் ஒப்படைத்தல்."),
        "dua_sleep_khalaqta_nafsi" to DuaText("நீ என் ஆத்மாவை படைத்தாய்", "யா அல்லாஹ்! என் ஆத்மாவை படைத்தாய், அதை மரிக்கச் செய்வதும் நீயே. அதன் மரணமும் உயிரும் உனக்கே. உயிருடன் வைத்தால் காப்பாற்று; மரணம் கொடுத்தால் மன்னி. யா அல்லாஹ்! உன்னிடம் ஆரோக்கியம் தேடுகிறேன்.", "தூங்குவதற்கு முன் — இப்னு உமர் (ரலி) அவர்களின் ரிவாயத்.", "நபி ﷺ தூக்கத்தில் இதை ஓதுமாறு கட்டளையிட்டனர்."),
        "dua_sleep_atamana" to DuaText("தூங்குவதற்கு முன் நன்றி", "எல்லாப் புகழும் அல்லாஹ்வுக்கே — அவன் எங்களுக்கு உண்ண வழங்கினான், குடிக்க வழங்கினான், எங்கள் தேவையை நிறைவேற்றினான், தங்குமிடம் கொடுத்தான். எத்தனை மனிதர்களுக்கு நிறைவேற்றுவதும் தங்குமிடமும் இல்லை.", "படுக்கையில் செல்லும்போது.", "நபி ﷺ படுக்கையில் செல்லும்போது இதைக் கூறுவார்கள்."),
        "dua_sleep_rabbas_samawat" to DuaText("வானங்களின் இறைவா — எங்கள் கடனை தீர்", "யா அல்லாஹ், வானங்கள், பூமி, மிகப்பெரிய அர்ஷ் இறைவனே, எல்லாவற்றின் இறைவா, தானிய விதையையும் கொட்டையையும் வெடிக்கச் செய்பவனே, தவ்ராத், இஞ்ஜீல், ஃபுர்கான் அருளியவனே! நீ அதன் நெற்றியைப் பிடித்திருக்கும் எந்த தீங்கிலிருந்தும் உன்னிடம் பாதுகாப்பு தேடுகிறேன். யா அல்லாஹ்! நீ முந்தியவன், உனக்கு முன் ஒன்றுமில்லை; நீ கடைசியானவன், உனக்குப் பின் ஒன்றுமில்லை; நீ வெளிப்படையானவன், உனக்கு மேல் ஒன்றுமில்லை; நீ மறைவானவன், உன்னிலிருந்து மறைவதில்லை. எங்கள் கடனை தீர்த்துவை, வறுமையிலிருந்து வளமாக்கு.", "தூங்குவதற்கு முன் வலது பக்கத்தில் — ஃபாத்திமா (ரலி) அவர்களுக்கு கற்பிக்கப்பட்டது.", "கடன் மற்றும் வறுமையிலிருந்து காப்பாற்றுவதற்கான துஆ."),
        "dua_sleep_fear" to DuaText("தூக்கத்தில் பயம் அல்லது கலக்கம்", "அல்லாஹ்வின் பரிபூர்ண கலிமாக்களிடம் அவனது கோபம், தண்டனை, அவனது அடியார்களின் தீங்கு, ஷைத்தான்களின் வஸ்வாஸ், அவர்கள் என்னிடம் வருவதிலிருந்து பாதுகாப்பு தேடுகிறேன்.", "தூக்கத்தில் கலக்கம் அல்லது பயம் ஏற்பட்டால்.", "இதை செய்தால் அது தீங்கு செய்யாது."),
        "dua_waking_afani" to DuaText("விழிக்கும்போது: என் ஆத்மாவை திருப்பி கொடுத்தான்", "எல்லாப் புகழும் அல்லாஹ்வுக்கே — அவன் என் உடலுக்கு ஆரோக்கியம் கொடுத்தான், என் ஆத்மாவை திருப்பி கொடுத்தான், என்னை அவனை நினைக்க அனுமதித்தான்.", "விழிக்கும்போது.", "புதிய காலையில் நன்றி."),
        "dua_allahu_rabbi" to DuaText("அல்லாஹ், அல்லாஹ் என் இறைவன்", "அல்லாஹ், அல்லாஹ் என் இறைவன்; அவனுடன் எதையும் இணைக்கவில்லை.", "துக்கம் அல்லது கலக்கத்தில் — நபி ﷺ அஸ்மா பின்த் உமைஸ் (ரலி) அவர்களுக்கு கற்பித்தது.", "கலக்கத்தில் தவ்ஹீதின் ஆதரவு."),
    )
}
